use serde::Serialize;use serde_json::Value;use sqlx::{FromRow,PgPool};
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct Performance{pub horizon:String,pub win_rate:f64,pub samples:i64,pub reliability:String,pub avg_return:f64}
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct History{pub id:String,pub symbol:String,pub decision:String,pub confidence:f64,pub horizon:String,pub realized_return:Option<f64>,pub outcome:String,pub created_at:String}
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct Reliability{pub name:String,pub reliability:f64,pub samples:i64}
#[derive(Debug,FromRow)]struct HistoryRow{symbol:String,decision:String,confidence:f64,decided_at_millis:i64,horizon_minutes:i32,directional_return_pct:f64,correct:bool}
#[derive(Clone)]pub struct Ledger{pool:PgPool}impl Ledger{pub async fn connect(url:&str)->Result<Self,sqlx::Error>{Ok(Self{pool:PgPool::connect(url).await?})}pub async fn performance(&self,symbol:&str)->Result<Vec<Performance>,sqlx::Error>{let mut out=Vec::new();for h in [15,60,240]{let row:(i64,Option<f64>,Option<f64>)=sqlx::query_as("SELECT COUNT(*)::BIGINT,AVG(CASE WHEN correct THEN 1.0 ELSE 0.0 END)::DOUBLE PRECISION,AVG(directional_return_pct)::DOUBLE PRECISION FROM decision_outcomes WHERE symbol=$1 AND horizon_minutes=$2").bind(symbol).bind(h).fetch_one(&self.pool).await?;let reliability=if row.0>=100{"HIGH"}else if row.0>=30{"MEDIUM"}else{"LOW"};out.push(Performance{horizon:format!("{} MIN",h),win_rate:row.1.unwrap_or(0.0)*100.0,samples:row.0,reliability:reliability.into(),avg_return:row.2.unwrap_or(0.0)})}Ok(out)}pub async fn history(&self,limit:i64)->Result<Vec<History>,sqlx::Error>{let rows:Vec<HistoryRow>=sqlx::query_as("SELECT l.symbol,l.decision,l.confidence,l.decided_at_millis,o.horizon_minutes,o.directional_return_pct,o.correct FROM decision_ledger l JOIN decision_outcomes o ON o.symbol=l.symbol AND o.decided_at_millis=l.decided_at_millis ORDER BY o.evaluated_at_millis DESC LIMIT $1").bind(limit.clamp(1,250)).fetch_all(&self.pool).await?;Ok(rows.into_iter().map(|r|History{id:format!("{}-{}-{}",r.symbol,r.decided_at_millis,r.horizon_minutes),symbol:r.symbol,decision:normalize(&r.decision),confidence:r.confidence,horizon:format!("{}M",r.horizon_minutes),realized_return:Some(r.directional_return_pct),outcome:if r.correct{"WIN"}else{"LOSS"}.into(),created_at:r.decided_at_millis.to_string()}).collect())}pub async fn reliability(&self,symbol:&str)->Result<Vec<Reliability>,sqlx::Error>{let rows:Vec<(bool,Value)>=sqlx::query_as("SELECT o.correct,l.metadata FROM decision_outcomes o JOIN decision_ledger l ON l.symbol=o.symbol AND l.decided_at_millis=o.decided_at_millis WHERE o.symbol=$1 AND o.horizon_minutes=60 ORDER BY o.evaluated_at_millis DESC LIMIT 500").bind(symbol).fetch_all(&self.pool).await?;let keys=[("Volume","volume_anomaly"),("Funding","funding_extreme"),("Order Book","order_book_imbalance"),("RSI","rsi_divergence")];Ok(keys.into_iter().map(|(name,key)|{let(mut hit,mut total)=(0.0,0.0);for(correct,m)in &rows{let strength=m.get(key).and_then(Value::as_f64).unwrap_or(50.0);let c=(strength-50.0).abs()/50.0;if c>=0.2{total+=c;if *correct{hit+=c}}}Reliability{name:name.into(),reliability:if total>0.0{hit/total*100.0}else{50.0},samples:rows.len() as i64}}).collect())}}
fn normalize(x:&str)->String{match x{"StrongLong"|"Long"=>"LONG","Short"|"StrongShort"=>"SHORT","NoTrade"=>"NO TRADE",_=>"WATCH"}.into()}
